import React, { useEffect, useState } from 'react';
import { progressionAPI } from '../services/api';
import { useAuth } from '../context/AuthContext';
const BattlePassPage=()=>{const {updateBalance}=useAuth();const[data,setData]=useState(null);const load=async()=>{try{const r=await progressionAPI.getOverview();setData(r.data)}catch(e){console.error(e)}};useEffect(()=>{load()},[]);const claim=async(level)=>{try{const r=await progressionAPI.claimBattlePass(level);await updateBalance(r.data.balance);await load();alert(`Récompense : ${r.data.reward.label}`)}catch(e){alert(e.response?.data?.detail||'Impossible de récupérer la récompense.')}};if(!data)return <div className="progression-loading"><div className="spinner-border"/></div>;return <div className="container pass-page"><section className="pass-hero"><div><span className="section-kicker">WELLCASE / SEASON {data.season}</span><h1>Le <em>Battle Pass.</em></h1><p>Gagne de l'XP et débloque des avantages pour tes ouvertures.</p></div><div className="pass-level"><span>NIVEAU</span><strong>{data.level}</strong><small>{data.xp.toLocaleString('fr-FR')} XP</small></div></section><div className="pass-track-head"><div><b>PROGRESSION DE SAISON</b><span>{data.xp.toLocaleString('fr-FR')} / 5 000 XP</span></div><div className="pass-progress"><i style={{width:`${Math.min(100,data.xp/5000*100)}%`}}/></div></div><div className="pass-grid">{data.battle_pass.map(r=><article key={r.level} className={`pass-reward ${r.unlocked?'unlocked':''} ${r.claimed?'claimed':''}`}><div className="pass-level-number">{r.level}</div><div className="pass-reward-icon">{r.type==='cash'?'€':r.type==='open3'?'×3':'×5'}</div><span>NIVEAU {r.level}</span><h3>{r.label}</h3><small>{r.xp.toLocaleString('fr-FR')} XP</small><button disabled={!r.unlocked||r.claimed} onClick={()=>claim(r.level)}>{r.claimed?'RÉCUPÉRÉ':r.unlocked?'RÉCUPÉRER':'VERROUILLÉ'}</button></article>)}</div><section className="multi-open-info"><div className="multi-icon">×5</div><div><span className="section-kicker">BONUS PREMIUM</span><h2>Ouvertures ×3 et ×5</h2><p>Les tickets débloqués apparaissent directement sur les caisses. Une ouverture multiple consomme un ticket et révèle chaque drop avec l'animation premium.</p></div><div className="ticket-count"><b>×3</b><strong>{data.open3_tokens}</strong><b>×5</b><strong>{data.open5_tokens}</strong></div></section></div>};export default BattlePassPage;
